func (s *Server) activityReport(ctx context.Context, args toolArgs) (string, error) {
	window := 24 * time.Hour
	if args.Since != "" {
		parsed, err := time.ParseDuration(args.Since)
		if err != nil || parsed <= 0 {
			return "", fmt.Errorf("since must be a positive duration such as 24h, got %q", args.Since)
		}
		window = parsed
	}
	return marshal(s.store.Activity(ctx, time.Now().UTC().Add(-window)))
}

// planPreview lets an agent check what a run would cost and whether it would
// be refused before spending a model call to find out.
func (s *Server) planPreview(ctx context.Context, args toolArgs) (string, error) {
	project, err := s.resolveProject(ctx, args.Project)
	if err != nil {
		return "", err
	}
	plan, err := app.BuildPlan(ctx, s.store, project)
	if err != nil {
		return "", err
	}
	return marshal(map[string]any{"plan": plan, "runnable": plan.Runnable()}, nil)
}
// Package mcp exposes GoalForge management as a Model Context Protocol
// server over stdio, so MCP clients (Claude Code, editors, agents) can
// inspect and steer projects conversationally. The transport is
// newline-delimited JSON-RPC 2.0 per the MCP stdio specification; only the
// tools capability is implemented, and every tool maps onto the same
// authoritative store operations the CLI and HTTP API use.
package mcp

import (
	"bufio"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"sync"

	"github.com/goalforge/goalforge/internal/scheduler"
	store "github.com/goalforge/goalforge/internal/store/sqlite"
)

const protocolVersion = "2025-06-18"

type Server struct {
	store   *store.Store
	queue   scheduler.Queue
	version string
	mu      sync.Mutex
	out     io.Writer
}

// New builds the MCP server. The queue is explicit for the same reason as the
// API's: enqueueing somewhere the worker does not drain is worse than refusing.
func New(s *store.Store, version string, queue scheduler.Queue) (*Server, error) {
	if s == nil {
		return nil, errors.New("store is required")
	}
	if queue == nil {
		return nil, errors.New("job queue is required")
	}
	if version == "" {
		version = "dev"
	}
	return &Server{store: s, queue: queue, version: version}, nil
}

type request struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      json.RawMessage `json:"id"`
	Method  string          `json:"method"`
	Params  json.RawMessage `json:"params"`
}

type response struct {
	JSONRPC string          `json:"jsonrpc"`
	ID      json.RawMessage `json:"id,omitempty"`
	Result  any             `json:"result,omitempty"`
	Error   *rpcError       `json:"error,omitempty"`
}

type rpcError struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

// Serve pumps newline-delimited JSON-RPC messages until input closes or ctx
// ends. Notifications (no id) never produce a response.
func (s *Server) Serve(ctx context.Context, in io.Reader, out io.Writer) error {
	s.out = out
	scanner := bufio.NewScanner(in)
	scanner.Buffer(make([]byte, 64*1024), 8*1024*1024)
	for scanner.Scan() {
		if ctx.Err() != nil {
			return ctx.Err()
		}
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}
		var req request
		if err := json.Unmarshal(line, &req); err != nil {
			s.reply(response{JSONRPC: "2.0", Error: &rpcError{Code: -32700, Message: "parse error: " + err.Error()}})
			continue
		}
		if req.ID == nil {
			continue // notification
		}
		result, rpcErr := s.dispatch(ctx, req)
		if rpcErr != nil {
			s.reply(response{JSONRPC: "2.0", ID: req.ID, Error: rpcErr})
			continue
		}
		s.reply(response{JSONRPC: "2.0", ID: req.ID, Result: result})
	}
	return scanner.Err()
}

